<?php require __DIR__.'/includes/bootstrap.php';$type=(string)get('type','articles');if(!in_array($type,['articles','docs','pages'],true))$type='articles';$st=db()->prepare('SELECT * FROM content_posts WHERE post_type=? AND status="publish" ORDER BY published_at DESC,id DESC');$st->execute([$type]);$rows=$st->fetchAll();$title=post_type_label($type);require __DIR__.'/includes/header.php';?><div class="max-w-7xl mx-auto px-3 sm:px-5 py-10"><div class="text-xs tracking-[.2em] text-blue-600 font-black"><?=e(strtoupper($type))?></div><h1 class="text-4xl sm:text-5xl font-black mt-2"><?=e($title)?></h1><div class="grid md:grid-cols-2 lg:grid-cols-3 gap-4 mt-8"><?php foreach($rows as $r):?><a href="<?=content_url($type,$r['slug'])?>" class="bg-white border rounded-[24px] overflow-hidden soft hover:-translate-y-0.5 transition"><div class="aspect-[16/9] bg-slate-100"><?php if($r['cover_image']):?><img src="<?=e($r['cover_image'])?>" class="w-full h-full object-cover"><?php endif;?></div><div class="p-5"><div class="font-black text-xl"><?=e($r['title'])?></div><p class="text-sm text-slate-500 mt-2 line-clamp-3"><?=e($r['excerpt'])?></p><div class="text-blue-600 font-black text-sm mt-4">Read more →</div></div></a><?php endforeach;?></div></div><?php require __DIR__.'/includes/footer.php'; ?>
